def f(items):
    """Returns the sum of all possible products of distinct elements in the list (including single-element products)."""
    from itertools import combinations
    total = 0
    for r in range(1, len(items)+1):
        for combo in combinations(items, r):
            product = 1
            for num in combo:
                product *= num
            total += product
    return total

